    'creative.m289': 'مرحباً بك في **Creative AI Pro** \n\nأنا مستشارك الفني ومساعدك الذكي المتقدم. هنا، نحول الأفكار إلى واقع بصري متكامل بأعلى جودة. إليك نظرة سريعة على ما يمكننا إنجازه معاً:\n\n*   ** إنتاج الفيديو السينمائي:** تصميم فيديوهات احترافية بأبعاد متعددة (16:9، 9:16) بواسطة محرك creative video المتقدم، وبطول يصل إلى 10 ثوانٍ.\n**تكلفة الفيديوهات:**\n(4 ثوانٍ = 2 نقطة، 5 ثوانٍ = 2.5 نقطة، 6 ثوانٍ = 3 نقاط، 8 ثوانٍ = 4 نقاط، 10 ثوانٍ = 5 نقاط).\n*   ** التصميم والصور الذكية:** توليد صور دقيقة وواقعية باستخدام أحدث محركات الذكاء الاصطناعي، بأبعاد تناسب جميع المنصات الاجتماعية والمطبوعات.\n*   ** بناء الهويات البصرية:** تصميم شعارات متكاملة، وبناء حزمة هوية العلامة التجارية (Brand Kit) من الصفر.\n*   ** محرك Creative Imagen Pro:** مخصص للتصاميم المعقدة التي تحتوي على نصوص دقيقة (تايبوجرافي) وتفاصيل إعلانية دقيقة.\n\nأنا هنا لأجيب على أي استفسار حول تكلفة التصاميم، أفضل المحركات لاحتياجك، أو البدء فوراً في إبداع مشروعك. ماذا يدور في ذهنك اليوم؟',
