    'creative.tour.roastery.geometry': 'Emblème circulaire représentant un rassemblement, accentué par un dessin au trait de feuilles de café.',
    'creative.tour.roastery.slogan': 'Chaque grain raconte une histoire, chaque recoin respire le patrimoine',
    'creative.tour.roastery.video': 'Zoom cinématographique lent sur les grains de café tournant sur une table rustique en chêne foncé, la vapeur chaude s\'élevant à travers les rayons de lumière dorée du matin. Le bruit du broyage mécanique s\'estompe dans l\'emblème chaleureux et lumineux de la torréfaction.',
