    'creative.tour.pharmacy.desc': 'Une pharmacie médicale d’avenir fusionnant les sciences de la santé avec des services d’IA rapides.',
    'creative.tour.pharmacy.industry': 'Santé et technologie',
    'creative.tour.pharmacy.geometry': 'Hélice croisée d\'ADN monoline représentant la recherche scientifique intégrée à la technologie.',
    'creative.tour.pharmacy.slogan': 'Une guérison intelligente alimentée par la technologie, fiable depuis des générations',
    'creative.tour.pharmacy.video': 'Un module de soins médicaux lumineux s’ouvre en douceur, affichant des mesures de santé par hologramme cybernétique en bleu profond. Les lignes lumineuses convergent pour mettre en valeur la vitrine de la pharmacie en verre cyan brillant.',
    'creative.tour.pharmacy.typo': 'JetBrains Mono (données techniques) + Inter (texte de confiance)',
