    'creative.tour.pharmacy.color.0.name': 'Technologie cyan brillant',
    'creative.tour.pharmacy.color.0.desc': 'Symbolise la pureté, la clarté, la science médicale avancée et la cyberintelligence.',
    'creative.tour.pharmacy.color.1.name': 'Obsidienne Gris Minuit',
    'creative.tour.pharmacy.color.1.desc': 'Offre un contraste saisissant et un prestige d\'entreprise, transmettant discipline et sécurité.',
    'creative.tour.burger.title': 'Burger Shop moderne et énergique',
    'creative.tour.burger.desc': 'Restaurant gastronomique de hamburgers grillés à la flamme avec une forte ambiance graffiti destinée aux jeunes.',
    'creative.tour.burger.industry': 'Nourriture et divertissement',
    'creative.tour.burger.geometry': 'Des traînées de flammes fusionnées avec des galettes de hamburger stylisées aux angles vifs, représentant l\'énergie et la vitesse.',
    'creative.tour.burger.slogan': 'Enflammez vos papilles, une pure folie culinaire à chaque bouchée',
    'creative.tour.burger.video': 'Montages rapides de flammes de feu rugissantes derrière une galette gastronomique juteuse tournant au ralenti. Le cheddar fondant éclabousse de façon spectaculaire, suivi d\'un soudain éclat de néon révélant l\'enseigne orange flamboyante de la devanture.',
    'creative.tour.burger.typo': 'Outfit Display (titres en gras) + Inter (haute lisibilité)',
    'creative.tour.burger.trait.0': 'Jeune',
    'creative.tour.burger.trait.1': 'Audacieux',
