    'creative.tour.burger.color.0.desc': 'Stimule le désir et l’appétit, évoquant l’énergie, la chaleur et le goût grillé à la flamme.',
    'creative.tour.burger.color.1.name': 'Rouge cerise audacieux',
    'creative.tour.burger.color.1.desc': 'Capte immédiatement l’attention visuelle, transmettant vitesse, audace et flair créatif.',
