    'creative.m109': 'Creative AI | Votre agence créative IA',
    'creative.m110': 'Notre backend construit automatiquement un contexte riche en injectant des éléments photographiques tels que des finitions mates et du bronze antique, incitant les moteurs génératifs aux normes les plus élevées.',
    'creative.m111': 'Ingénierie rapide',
    'creative.m112': 'Nous fusionnons les formats d\'affichage des panneaux d\'affichage (tels que 2:1 et 3:1) pour garantir des affichages typographiques avec une esthétique absolue correspondant aux angles de distance réels des piétons.',
    'creative.m113': 'Architecture géométrique',
    'creative.m114': 'Les couleurs ne sont jamais choisies au hasard. Nous étudions les impressions neuronales. L\'ambre représente l\'héritage et l\'authenticité, tandis que le cyan représente l\'intelligence et le soin précis du cloud.',
    'creative.m115': 'Psychologie des couleurs',
    'creative.m116': 'Veuillez choisir une activité dans le panneau et cliquez sur « Démarrer la simulation de pensée » pour regarder les algorithmes créatifs cartographier votre marque.',
