    'creative.m134': 'Processus de réflexion actif...',
    'creative.m135': 'Cliquez pour démarrer le cerveau du générateur et observez comment il traite les entrées pour synthétiser les fichiers.',
    'creative.m136': 'Console de contrôle de simulation',
    'creative.m137': 'Sélectionnez un scénario de marque',
    'creative.m138': 'Contrairement aux générateurs aléatoires, notre algorithme met en œuvre des principes d\'ingénierie stricts. Il analyse la sémantique, utilise la psychologie des couleurs, choisit des cadres géométriques, conçoit des invites et calcule des rapports d\'aspect environnementaux précis pour une esthétique la plus fine.',
    'creative.m139': 'Comment l’algorithme crée-t-il le luxe et la créativité ?',
