    'creative.m204': 'Bonjour ! Je suis votre assistant Creative AI. Comment puis-je vous aider à concevoir aujourd’hui ?',
    'creative.m205': 'Bienvenue sur **Creative AI** \n\nJe suis votre assistant de conception graphique intelligent. Je peux vous aider à transformer vos idées en conceptions professionnelles en un clic. Voici un aperçu rapide de mes fonctionnalités :\n\n* ** Génération d\'images intelligente :** Conception d\'images haute résolution adaptée à vos besoins.\n* ** Interface simple :** Modifiez et personnalisez vos idées simplement en discutant avec moi.\n* ** Dimensions multiples :** Prise en charge des dimensions standard 1:1.\n\nJe suis toujours prêt. Qu’aimeriez-vous concevoir aujourd’hui ?',
    'creative.m206': ' Découvrez ce superbe design créé par Creative AI ! \\n\\n Lien :\\n{{p0}}\\n\\nCréez dès maintenant votre identité de marque et vos vidéos cinématographiques grâce à la puissance de l\'IA !',
