    'creative.m288': 'Effacer toutes les discussions',
    'creative.m289': 'Bienvenue sur **Creative AI Pro** \n\nJe suis votre assistant IA avancé et consultant créatif. Ici, nous transformons les idées en réalités visuelles époustouflantes. Voici un aperçu de ce que nous pouvons réaliser ensemble :\n\n* ** Production vidéo cinématographique :** Vidéos professionnelles en dimensions (16:9, 9:16) utilisant le moteur vidéo créatif avancé, jusqu\'à 10 secondes par clip.\n**Coûts vidéo :**\n(4s = 2 pts, 5s = 2,5 pts, 6s = 3 pts, 8s = 4 pts, 10s = 5 pts).\n* ** Conception et imagerie intelligentes :** Génération d\'images très détaillées et réalistes à l\'aide des derniers moteurs d\'IA, parfaitement dimensionnées pour n\'importe quelle plate-forme.\n* ** Création d\'identité de marque :** Conception complète du logo et génération complète d\'un kit de marque à partir de zéro.\n* ** Creative Imagen Pro Engine :** Spécialisé pour les conceptions complexes comportant une typographie et des détails publicitaires précis.\n\nJe suis là pour répondre à toutes vos questions sur les coûts de conception, les moteurs les mieux adaptés à vos besoins ou pour commencer à créer immédiatement. Qu’est-ce qui vous préoccupe aujourd’hui ?',
