    'creative.m112': 'Wir kombinieren die Seitenverhältnisse von Werbetafeln (z. B. 2:1 und 3:1), um Typografiedarstellungen mit absoluter Ästhetik zu gewährleisten, die den tatsächlichen Fußgängerentfernungswinkeln entsprechen.',
    'creative.m113': 'Geometrische Architektur',
    'creative.m114': 'Farben werden niemals zufällig ausgewählt. Wir untersuchen neuronale Eindrücke. Bernstein steht für Tradition und Authentizität, während Cyan für präzise Cloud-Intelligenz und Sorgfalt steht.',
