    'creative.m289': 'Willkommen bei **Creative AI Pro** \n\nIch bin Ihr fortgeschrittener KI-Assistent und kreativer Berater. Hier verwandeln wir Ideen in atemberaubende visuelle Realitäten. Hier ist ein kurzer Blick darauf, was wir gemeinsam erreichen können:\n\n* ** Filmische Videoproduktion: ** Professionelle Videos in den Abmessungen (16:9, 9:16) mit der fortschrittlichen kreativen Video-Engine, bis zu 10 Sekunden pro Clip.\n**Videokosten:**\n(4er = 2 Punkte, 5er = 2,5 Punkte, 6er = 3 Punkte, 8er = 4 Punkte, 10er = 5 Punkte).\n* ** Intelligentes Design und Bildmaterial: ** Hochdetaillierte und realistische Bilderzeugung mit den neuesten KI-Engines, perfekt dimensioniert für jede Plattform.\n* **Erstellung der Markenidentität:** Vollständiges Logo-Design und umfassende Erstellung des Marken-Kits von Grund auf.\n* ** Creative Imagen Pro Engine:** Spezialisiert auf komplexe Designs mit präziser Typografie und Werbedetails.\n\nIch bin hier, um alle Fragen zu Designkosten und den besten Motoren für Ihre Anforderungen zu beantworten oder sofort mit der Entwicklung zu beginnen. Was beschäftigt Sie heute?',
