    'creative.tour.burger.industry': 'Comida e entretenimento',
    'creative.tour.burger.geometry': 'Trilhas de chamas fundidas com hambúrgueres estilizados em ângulos agudos, representando energia e velocidade.',
    'creative.tour.burger.slogan': 'Acenda suas papilas gustativas, pura loucura culinária em cada mordida',
    'creative.tour.burger.video': 'Edições em ritmo acelerado de chamas de fogo atrás de um suculento hambúrguer gourmet girando em câmera lenta. O queijo cheddar derretido respinga dramaticamente, seguido por um súbito ataque de néon revelando a placa laranja da vitrine da loja.',
    'creative.tour.burger.typo': 'Outfit Display (manchetes em negrito) + Inter (alta legibilidade)',
