    'creative.m109': 'Creative AI | Sua agência criativa de IA',
    'creative.m110': 'Nosso back-end constrói um contexto rico automaticamente, injetando dicas fotográficas como acabamentos foscos e bronze antigo, levando os motores generativos aos mais altos padrões.',
    'creative.m111': 'Engenharia imediata',
    'creative.m112': 'Combinamos proporções de outdoor (como 2:1 e 3:1) para garantir exibições tipográficas com estética absoluta correspondente a ângulos reais de distância de pedestres.',
    'creative.m113': 'Arquitetura Geométrica',
    'creative.m114': 'As cores nunca são escolhidas aleatoriamente. Estudamos impressões neurais. O âmbar representa herança e autenticidade, enquanto o ciano retrata inteligência e cuidado precisos na nuvem.',
    'creative.m115': 'Psicologia das Cores',
