    'creative.m136': 'Console de controle de simulação',
    'creative.m137': 'Selecione um cenário de marca',
    'creative.m138': 'Ao contrário dos geradores aleatórios, nosso algoritmo implementa princípios rígidos de engenharia. Ele analisa a semântica, utiliza a psicologia das cores, escolhe estruturas geométricas, projeta prompts e calcula proporções ambientais precisas para obter a melhor estética.',
